#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 31

int main(int argc, char *argv[])
{
    /* ---------- argument validation ---------- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);

    if (len == 0 || len > MAXLEN) {
        puts("INVALID_INPUT");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* ---------- copy the tape ---------- */
    char tape[MAXLEN];
    memcpy(tape, in, len);

    /* ---------- Turing‑machine simulation ----------
       The head starts on the right‑most cell (least significant bit).
       Every move of the head (left or right) counts as one step.
    */
    long steps = 0;
    long pos = (long)len - 1;          /* head position */
    bool overflow = false;

    while (pos >= 0 && tape[pos] == '1') {
        tape[pos] = '0';               /* write 0 */
        ++steps;                       /* write step */
        --pos;                         /* move left */
        ++steps;                       /* move step */
    }

    if (pos >= 0) {                    /* found a 0 → turn it into 1 */
        tape[pos] = '1';
        ++steps;                       /* write step */
    } else {                           /* all bits were 1 → overflow */
        overflow = true;
        /* the machine has already turned every cell into '0' */
    }

    /* ---------- output ---------- */
    if (overflow) {
        puts("OVERFLOW");
    } else {
        printf("result=");
        for (size_t i = 0; i < len; ++i)
            putchar(tape[i]);
    }
    printf(" steps=%ld\n", steps);
    return 0;
}
